insert into public.projects (title, description, tech, category, github, demo, featured, has_interactive_demo, sort_order) values
  ('Git Release Analyzer', 'AI tool that compares release branches using Git APIs, producing rich summaries of code changes, commits, MRs, developers, and reviewers. Generates separate non-technical Business Summaries and detailed Technical summaries for deployment risk auditing.', array['Python', 'Git API', 'OpenAI', 'FastAPI', 'React']::text[], 'AI', 'https://github.com/khazaShaik', null, true, true, 0),
  ('Agent Studio — Onboard Any Service, Generate Its Tests', 'A generic tool that takes a service from "here is my repo" to a running test suite. It ingests seven source types — Git code, Swagger/OpenAPI, Confluence runbooks, database schema, qTest and Splunk — into a searchable per-service domain, builds a cross-source dependency graph, then generates positive, negative and edge scenarios filled with data that satisfies real schema constraints and executes them with per-step validation and reporting. Nothing is service-specific: onboarding a new API is configuration, not code. The LLM handles extraction and scenario design while deterministic code runs and validates every step, so failures stay reproducible.', array['React 19', 'TypeScript', 'Python', 'FastAPI', 'LangGraph', 'RAG', 'pgvector', 'SSE']::text[], 'AI', 'https://github.com/khazaShaik', null, true, true, 1),
  ('DocuMind — RAG-Powered Doc Assistant', 'Retrieval-augmented Q&A system over technical documentation. Ingests PDFs and Markdown, chunks with recursive splitting, embeds via OpenAI, and retrieves via ChromaDB with hybrid search and cross-encoder reranking. Returns answers with cited sources and holds up well against a hand-built evaluation set.', array['Python', 'LangChain', 'OpenAI', 'ChromaDB', 'FastAPI', 'RAG']::text[], 'AI', 'https://github.com/khazaShaik', null, true, false, 2),
  ('AgentFlow — Multi-Agent Workflow', 'Multi-agent orchestration system built with LangGraph. Four agents (planner, retriever, executor, critic) collaborate through shared state with tool calling, function routing, and self-correction loops. It triages GitHub issues and drafts contextual responses, taking a lot of the manual work out of issue triage.', array['Python', 'LangGraph', 'LangChain', 'OpenAI', 'Function Calling', 'AI Agents']::text[], 'AI', 'https://github.com/khazaShaik', null, true, false, 3),
  ('T-Mobile SCM Platform', 'Cloud-native supply chain platform used across thousands of T-Mobile retail stores. Owns the DRI / DRO / DLM modules that handle a high daily volume of inventory transactions, with Kafka async flows, Cassandra-tuned hot paths, and Kubernetes orchestration. Currently delivering the TIMO Console and TIMO iOS app.', array['Spring Boot', 'Java 17', 'Apigee', 'Cassandra', 'Kafka', 'Kubernetes', 'Angular 16']::text[], 'Enterprise', null, null, false, false, 4),
  ('CREW Rest Day Logic — Union Pacific Railroad', 'Designed and delivered Rest Day functionality for Union Pacific Railroad''s crew allocation system, serving a ~4,000-member crew workforce with calculations running daily. Built it as a configurable rule engine that enforces the mandated rest gap between shifts (12–24 hours by role and policy), integrated end to end into the CREW module.', array['Spring Boot', 'Java 11', 'Reactive Programming', 'Angular 11', 'Splunk']::text[], 'Enterprise', null, null, false, false, 5),
  ('ERCS — Electronic Receipt System', 'Electronic receipt and confirmation system for CCIL, handling collateral notices across its member network — India''s major banks and financial institutions clearing through CCIL and NSE in the money, G-Sec, and derivative markets. Live in production at enotice.ccilindia.com.', array['Spring', 'REST', 'Oracle', 'AngularJS', 'JPA', 'Tomcat']::text[], 'Enterprise', null, 'https://enotice.ccilindia.com', false, false, 6),
  ('eTokens — Coupons Management', 'SEO-friendly coupons management platform enabling merchants to create, distribute, and track coupon campaigns with real-time analytics and redemption tracking.', array['Angular', 'Spring Boot', 'Java', 'REST API']::text[], 'Enterprise', 'https://github.com/khazaShaik', null, false, false, 7),
  ('Vendor Management System (VMS)', 'Platform for businesses to manage their contingent vendor ecosystem — obtaining quotes with pricing, capabilities, and turnaround times in one place.', array['Java', 'Spring', 'AngularJS', 'REST', 'Oracle']::text[], 'Enterprise', 'https://github.com/khazaShaik/VMS', null, false, false, 8);
insert into public.experience (role, company, duration, location, client, website, highlights, tech_ai, tech, sort_order) values
  ('Systems Engineer', 'Tata Consultancy Services (TCS)', 'Jun 2025 – Present', 'Bengaluru, India', 'If P&C Insurance', null, array['Develop and support enterprise P&C insurance applications covering core policy and business workflows, using Java, Spring, REST/SOAP services, and enterprise integration technologies', 'Build and enhance backend services for insurance workflows, integrating application services with mainframe systems, databases, messaging infrastructure, and downstream enterprise applications', 'Work across the full development lifecycle — analyzing requirements, designing solutions, developing features, troubleshooting production issues, and supporting releases across enterprise environments', 'Develop event-driven integrations using Kafka and messaging systems, enabling reliable communication between distributed insurance applications and downstream services', 'Work with PostgreSQL, Cassandra, and MongoDB for application data and test-data management, including designing queries, integrations, and data validation for business workflows', 'Contribute to Angular and React-based frontend applications, building user-facing workflows and integrating them with backend REST APIs', 'Lead a team of engineers and mentor junior developers through technical discussions, code reviews, design decisions, troubleshooting, and sprint delivery', 'Contribute to AI-assisted engineering initiatives using Python, LangChain, LLMs, and RAG to improve KT, data generation and developer productivity', 'Improve quality and reliability of insurance applications through automated testing, integration validation, and systematic analysis of production issues']::text[], array['Python', 'FastAPI', 'LangChain', 'RAG', 'AI Agents', 'React']::text[], array['Java', 'Spring Boot', 'Angular 17', 'SOAP/REST APIs', 'Microservices', 'Redis', 'Kafka', 'Cassandra', 'MongoDB', 'Azure Cloud']::text[], 0),
  ('Systems Engineer', 'Tata Consultancy Services (TCS)', 'Jun 2022 – Nov 2025', 'Bengaluru, India', 'Canadian Imperial Bank of Commerce (CIBC)', null, array['Owned end-to-end development and enhancement of enterprise banking services using Java, Spring Boot, and microservices, covering requirement analysis, solution design, development, testing, deployment, and production support', 'Enhanced and modernized existing backend services and REST/SOAP APIs by improving service performance, reliability, error handling, validation, and maintainability while integrating with enterprise and legacy systems', 'Designed and implemented event-driven integrations using Apache Kafka and enterprise messaging, improving communication between distributed services and supporting reliable processing across banking applications', 'Worked across the complete release lifecycle including code reviews, automated and integration testing, CI/CD deployments, production releases, incident troubleshooting, root-cause analysis, and implementation of service improvements', 'Led a team of engineers in delivering application enhancements and production fixes, providing technical guidance, reviewing designs and code, resolving complex issues, and driving continuous improvements to application stability and service quality']::text[], array[]::text[], array['Java', 'Spring Boot', 'Hibernate', 'Angular 17', 'SOAP/REST APIs', 'Microservices', 'Kafka', 'Oracle', 'AWS']::text[], 1),
  ('Associate Software Engineer', 'UST', 'Jan 2021 – Jun 2022', 'Bengaluru, India', 'Walmart', null, array['Developed and maintained enterprise data solutions for retail business workflows, working across SQL development, data analysis, testing, deployment, and production support', 'Developed and optimized complex SQL queries and stored procedures using joins, subqueries, CTEs, aggregations, conditional logic, and data transformations to process and validate business data', 'Created and enhanced database stored procedures for business logic, data processing, validations, and source-to-target transformations, improving the reliability and consistency of downstream data processes', 'Supported ETL and data integration workflows by performing data extraction, cleansing, transformation, reconciliation, and source-to-target validation across multiple enterprise data sources', 'Investigated data discrepancies and production issues through SQL-based analysis and root-cause investigation, implementing data fixes and query optimizations to improve data accuracy, performance, and reliability']::text[], array[]::text[], array['SQL', 'Stored Procedures', 'Advanced SQL', 'ETL', 'Data Integration', 'Data Transformation', 'Data Validation', 'Data Quality', 'Data Analysis', 'Database Management', 'Python', 'Pandas', 'Data Cleansing', 'Data Reconciliation', 'Source-to-Target Mapping', 'Query Optimization', 'Production Support']::text[], 2),
  ('Software Engineer', 'Gove.Co', 'June 2020 – Oct 2020', 'Bengaluru, India', 'Fleet Management System', null, array['Developed and enhanced a cloud-based Fleet Management System using Java and enterprise web technologies, supporting vehicle, asset, driver, maintenance, and operational workflows for a manufacturing-focused business platform', 'Designed and implemented backend business logic and RESTful APIs for fleet and asset management workflows, including vehicle tracking, maintenance operations, status management, and operational data processing', 'Developed database-driven features and optimized SQL queries to manage fleet, asset, service, and operational data while ensuring data consistency and reliable application performance', 'Worked across the complete product development lifecycle in a startup environment — from requirement analysis and feature development to testing, deployment, production troubleshooting, and continuous improvement of platform functionality', 'Collaborated closely with product and engineering teams to deliver new features, resolve production issues, improve application performance, and enhance the usability and reliability of the cloud platform']::text[], array[]::text[], array['Java', 'Spring Boot', 'Oracle', 'Redis', 'REST APIs', 'J2EE', 'Web Services', 'SQL', 'JDBC', 'Database', 'JavaScript', 'HTML', 'CSS', 'GitLab CI/CD']::text[], 3),
  ('Software Intern', 'IPrimed Solutions Pvt. Ltd. ', 'Aug 2018 - Oct 2018', 'Bengaluru, India', null, null, array['Gained hands-on experience in Java application development, REST APIs, SQL, database integration, debugging, testing, and implementing application features as part of the software development lifecycle']::text[], array[]::text[], array['Java', 'REST APIs', 'SQL', 'JDBC', 'JavaScript', 'HTML', 'CSS']::text[], 4),
  ('Web Development Intern', 'CDD Society', 'Mar 2018 - Jun 2018', 'Bengaluru, India', null, 'https://www.cddindia.org/', array['Supported web application development and maintenance through Java, SQL, application testing, debugging, feature enhancements, and collaboration with the development team across the software development lifecycle', 'Developed a CMS-driven UI, including a responsive carousel/slideshow and cross-device layouts.', 'Designed a contact form and integrated social sharing for Instagram, Facebook, Twitter, and YouTube.']::text[], array[]::text[], array['CMS', 'JavaScript', 'HTML', 'CSS', 'Git']::text[], 5);
