insert into public.profile (singleton, name, title, location, email, phone, linkedin, linkedin_url, github, github_url, summary, hero, about, highlights, education) values
  (true, 'Akhil Mukesh', 'Software Engineer, Lead (Java · Python · React/Angular · AI)', 'Bengaluru, India', 'akhil1997mukesh@gmail.com', '+91 8618097296', 'https://www.linkedin.com/in/akhil-mukesh-43376a126/', 'https://www.linkedin.com/in/akhil-mukesh-43376a126/', 'https://github.com/AkhilMukesh', 'https://github.com/AkhilMukesh', 'Full Stack Engineer with 6+ years building, scaling enterprise systems and owning its architecture end to end. Deep across the stack — Java and Spring Boot, Angular and React, Kafka event-driven systems, PostgresSQL and Cassandra/MongoDB on AWS, Azure, and Kubernetes — plus production AI: RAG pipelines, tool-calling agents, and LLM features in Python. Proven track record of transforming systems from frequent P1 production incidents to highly reliable platforms with minimal critical outages.', '{"leadLabel":"Full Stack Engineer","tagline":"With 6+ years building web applications end to end — Java and Spring Boot on the backend, Angular and React on the frontend, and Python-based AI systems including LLMs, RAG pipelines, and tool-calling agents.","sub":"I lead a team at TCS on an AI-powered orchestration platform — owning its architecture, mentoring the developers on it, and building the critical paths myself. LLM features, retrieval (RAG), and agents in Python, held to the same bar as everything else I ship."}'::jsonb, '["I''m a full stack engineer. Most of my {years} years have gone into building and integrating Java and Spring Boot services with Angular and React front-ends for enterprise clients — the kind of systems where a lot of people depend on things not breaking.","I''m comfortable across the whole stack. On a typical feature I''ll design the API and data model, write the back-end and the UI, wire up the messaging and caching, and make sure it''s observable and stable once it ships. I care about the parts that don''t show up in a demo: error handling, edge cases, and what happens under load.","I also build AI into products — LLM-powered features, retrieval (RAG), and small tool-calling agents, mostly in Python with LangChain and vector databases. It gets the same testing, logging, and review as anything else I ship, because a clever prototype that falls over in production isn''t worth much.","Outside of work: cricket,gaming and reading about how other engineers build things, and the occasional deep-dive into something completely unrelated."]'::jsonb, '[{"eyebrow":"What I do","stat":"Build full stack, end to end","hint":"Java · Python · Spring Boot · Angular / React · AI","detail":"I own features from the API and data model to the UI, with the messaging, testing, and observability that keep them reliable."},{"eyebrow":"Track record","stat":"{years} years · 3 companies","hint":"TCS · UST · Gove.Co","detail":"Shipped and maintained enterprise systems across Insurance, supply chain, Banking and finance — the kind people depend on daily."},{"eyebrow":"Current role","stat":"Leading a team","hint":"Tata Consultancy Services (TCS) · If P&C Insurance","detail":"Leading a team while owning architecture and critical development for an AI-powered test orchestration platform — Java, Spring Boot, Kafka, Kubernetes, and Python-based LLM, RAG, and agentic workflows."},{"eyebrow":"Looking for","stat":"A strong product team","hint":"Remote · Hybrid · On-site · GCC","detail":"Somewhere I can own features end to end across the stack, and keep bringing AI in where it genuinely helps."}]'::jsonb, '{"degree":"B.Tech/BE, Information Science Engineering","school":"Visvesvaraya Technological University (VTU), India"}'::jsonb);
